package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.zip.ZipException;
import org.apache.commons.compress.utils.Lang;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Zip64ExtendedInformationExtraField_parseFromLocalFileData_TriageGen0Test {

    private static final int DWORD = 8;
    private static final int WORD = 2;

    @Test
    public void testParse_LengthZero() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] buffer = new byte[10];
        // Should return immediately without exception
        field.parseFromLocalFileData(buffer, 0, 0);
    }

    @Test(expected = ZipException.class)
    public void testParse_LengthTooSmall() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] buffer = new byte[10];
        // length < 2 * DWORD (16)
        field.parseFromLocalFileData(buffer, 0, 15);
    }

    @Test
    public void testParse_OnlySizeAndCompressedSize() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        int length = 2 * DWORD;
        byte[] buffer = new byte[length];
        ByteBuffer bb = ByteBuffer.wrap(buffer);
        bb.putLong(100L); // size
        bb.putLong(50L);  // compressedSize

        field.parseFromLocalFileData(buffer, 0, length);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(50L, field.getCompressedSize().longValue());
        // Others should be null/default
        assertEquals(null, field.getRelativeHeaderOffset());
        assertEquals(null, field.getDiskStartNumber());
    }

    @Test
    public void testParse_WithRelativeHeaderOffset() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        // 2 * DWORD + 1 * DWORD
        int length = 3 * DWORD;
        byte[] buffer = new byte[length];
        ByteBuffer bb = ByteBuffer.wrap(buffer);
        bb.putLong(100L); // size
        bb.putLong(50L);  // compressedSize
        bb.putLong(200L); // relativeHeaderOffset

        field.parseFromLocalFileData(buffer, 0, length);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(50L, field.getCompressedSize().longValue());
        assertEquals(200L, field.getRelativeHeaderOffset().longValue());
        assertEquals(null, field.getDiskStartNumber());
    }

    @Test
    public void testParse_FullFields() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        // 2 * DWORD + 1 * DWORD + 1 * WORD
        int length = 3 * DWORD + WORD;
        byte[] buffer = new byte[length];
        ByteBuffer bb = ByteBuffer.wrap(buffer);
        bb.putLong(100L);  // size
        bb.putLong(50L);   // compressedSize
        bb.putLong(200L);  // relativeHeaderOffset
        bb.putShort((short) 5); // diskStart (ZipLong reads 2 bytes via WORD logic in code)

        field.parseFromLocalFileData(buffer, 0, length);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(50L, field.getCompressedSize().longValue());
        assertEquals(200L, field.getRelativeHeaderOffset().longValue());
        assertEquals(5L, field.getDiskStartNumber().longValue());
    }

    @Test
    public void testParse_WithOffset() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        int offset = 5;
        int length = 2 * DWORD;
        byte[] buffer = new byte[offset + length];
        ByteBuffer bb = ByteBuffer.wrap(buffer);
        bb.position(offset);
        bb.putLong(100L);
        bb.putLong(50L);

        field.parseFromLocalFileData(buffer, offset, length);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(50L, field.getCompressedSize().longValue());
    }
}
